"""Reporting-only reading of complete native study outputs; no evaluator imports."""
from pathlib import Path
import json, sqlite3, hashlib
R=Path(__file__).resolve().parent
read=lambda name:json.loads((R/name).read_text())
write=lambda name,data:(R/name).write_text(json.dumps(data,indent=2)+'\n')
P='aries_integrated_plant__'
rows=read('results/cases.json')['cases']; by={r['case']:r for r in rows}
proposals=read('proposed-points.json')['cases']; proposed={r['case']:r for r in proposals}
get=lambda row,owner,field,calc='evaluate':row['outputs'][P+owner+'__'+calc+'__'+field]
price=lambda row:get(row,'lifecycle_price','lcoe')
base=by['no-breeding-credit'];feed=by['assumed-new-tritium-feed-100']
assert all(r['state']=='completed' and r['inputs']==proposed[r['case']]['point'] for r in rows)
assert read('results/verification_summary.json')['outcome']=='pass'
store=R/'results/native'/f'{R.name}.db'
conn=sqlite3.connect('file:'+str(store)+'?mode=ro&immutable=1',uri=True)
counts=dict(conn.execute('select state,count(*) from attempt_transitions group by state'))
assert counts=={'started':64,'committed':64}
assert conn.execute('select max(attempt_number) from attempt_transitions').fetchone()[0]==1
conn.close()
failures=[{'case':r['case'],'net_mw':get(r,'plant_ledger','net_electric'),'lcoe':price(r),'verdicts':{k:v for k,v in r['verdicts'].items() if v!='satisfied'}} for r in rows if any(v!='satisfied' for v in r['verdicts'].values())]
axes=read('axis-plan.json')['axes']; axis_summary=[]
for a in axes:
 for arm,anchor in [('no-credit',base),('named-feed',feed)]:
  selected=[r for r in rows if proposed[r['case']]['axis']==a['axis'] and proposed[r['case']]['arm']==arm]
  if selected:
   selected=[anchor]+selected
   axis_summary.append({'axis':a['axis'],'arm':arm,'minimum':min(price(r) for r in selected),'maximum':max(price(r) for r in selected),'cases':[r['case'] for r in selected]})
financial=[r for r in rows if not r['case'].startswith(('literal-','nominal-source','density-','he-area'))]
summary={'scope':'Native finite-LCOE results; isolated refusals separate. Unequal engineered sensitivity windows, no probability or optimum.',
 'cases':64,'attempts':counts,'evaluator_reruns':0,'numeric_outputs_per_case':sorted({len(r['outputs']) for r in rows}),
 'all_scoped_checks_satisfied':64-len(failures),'adverse_cases':failures,'axis_ranges':axis_summary,
 'range_all_cases':{'min':min(price(r) for r in rows),'max':max(price(r) for r in rows)},
 'baseline_no_credit':price(base),'baseline_feed100':price(feed),
 'verification':{'channels_per_case':364,'predicates_per_case':14,'scalar_checks':64*364,'predicate_checks':64*14}}
write('results/analysis.json',summary)
lines=['# Conditional lifecycle study results','', '[AGENT executor reading] All 64 declared points completed in one native attempt each at execution commit `f4ea479506cae17d2a9aafe0f914346c555193e7`. Independent all-point verification passes 23,296 scalar and 896 predicate comparisons. Four completed cases retain engineering violations; 60 satisfy all 14 represented checks. Financial definedness does not qualify unsupported physics or supply capability. All report values below are read from `results/cases.json`; derived differences are reporting arithmetic.','', '## Named supply cases','', 'The assumed integrated baseline produces 423.106794 MW net. Internal exhaust recycling is already accounted for. New feed is net usable extracted breeder supply entering after extraction losses, in kg per calendar year. Its service allowance is additional to existing installed fuel/blanket capital and O&M; it is not a third-party purchase or a demonstrated breeding capability.','', '| Native case | New feed kg/y | Service million USD2004/y | External T kg/y | Curtailed feed kg/y | Integrated USD2004/MWh | Source-conditioned USD2004/MWh |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for name in ['no-breeding-credit','new-feed-50.0','assumed-new-tritium-feed-100','new-feed-110.0','supply-service-10000000.0','supply-service-100000000.0']:
 r=by[name];lines.append(f"| {name} | {r['inputs'][P+'fuel_inventory__annual_recovery_kg']:.0f} | {r['inputs'][P+'finance__supply_service_annual']/1e6:.0f} | {get(r,'lifecycle_accounts','external_shortfall'):.6f} | {get(r,'lifecycle_accounts','curtailed_feed'):.6f} | {price(r):.6f} | {get(r,'source_lifecycle_price','lcoe'):.6f} |")
lines += ['', 'Baseline gross new-tritium need is 104.667707 kg/calendar year. Assumed feed of 110 kg/year crosses the zero-purchase floor and curtails the excess without sales revenue. No point establishes that this extraction capability exists or that increasing it has the declared service cost.', '', '## Complete baseline contributions','', '| Contribution USD2004/MWh | No credit | Feed100 / service30m | Source-conditioned feed100 |','| --- | ---: | ---: | ---: |']
for field,label in [('capital_lcoe','Financed capital'),('om_lcoe','Routine O&M'),('tritium_lcoe','External tritium'),('deuterium_lcoe','Deuterium'),('consumables_lcoe','Consumables'),('imports_lcoe','Grid imports'),('supply_lcoe','New-feed service'),('replacement_lcoe','Blanket/divertor/LiPb events'),('other_overhaul_lcoe','Other major overhaul'),('terminal_lcoe','Gross terminal disposal/decommissioning'),('salvage_lcoe','Salvage credit'),('lcoe_sum','Total')]:
 lines.append(f"| {label} | {get(base,'lifecycle_accounts',field):.9f} | {get(feed,'lifecycle_accounts',field):.9f} | {get(feed,'source_lifecycle_accounts',field):.9f} |")
lines+=['', 'Constant USD2004, real discount 5%, 40 calendar operating years and availability .85 define these baseline values. Overnight capital receives midpoint construction financing once over six years. Operating energy and recurring charges fall at each year end; dated replacement events exclude an event exactly at terminal life. The annual replacement reserve is published but excluded from LCOE. A separate 5%-of-capital overhaul at year 20 covers non-blanket scheduled refurbishment. Terminal gross liability is 10% of capital and salvage 2%, both at year 40; availability already includes downtime. No additional replacement outage penalty is charged.','', '| Native baseline account | Value |','| --- | ---: |']
for owner,field,unit in [('cost_ledger','overnight','USD2004'),('lifecycle_accounts','financed_capital','USD2004'),('lifecycle_accounts','idc','USD2004'),('lifecycle_accounts','annual_energy','MWh/y'),('lifecycle_accounts','pv_energy','discounted MWh'),('replacement','event_count','events'),('replacement','event_cost','USD2004/event'),('lifecycle_accounts','pv_replacement','USD2004'),('lifecycle_accounts','gross_terminal','USD2004'),('lifecycle_accounts','salvage','USD2004')]:lines.append(f'| {owner}.{field} ({unit}) | {get(base,owner,field):.9f} |')
lines+=['', '## Financial sensitivity','', 'The following ranges include the matching baseline and the declared changed points. Windows differ between axes; spans are neither probabilities nor a ranking independent of chosen bounds. All amounts are conditional USD2004/MWh.','', '| Axis | Supply scenario | Observed minimum | Observed maximum |','| --- | --- | ---: | ---: |']
for a in axis_summary:lines.append(f"| {a['axis']} | {a['arm']} | {a['minimum']:.6f} | {a['maximum']:.6f} |")
lines+=['', 'External tritium price dominates the selected no-credit window: its 10–100 million USD2004/kg endpoints produce 448.398872–3467.940324 USD2004/MWh. This is a broad assumed supply-price range, not a dated market forecast. Zero real discount is supported; the zero-discount and tiny-rate cases approach the same dated-cashflow limit. At zero discount, construction duration produces no financing increment. Terminal, salvage, overhaul and replacement contributions remain charged explicitly through the chosen convention.','', '## Fixed supply under availability and demand changes','', '| Native case | Availability | Density amplitude m^-3 | Fixed feed kg/y | Net MW | External T kg/y | Curtailed kg/y | USD2004/MWh |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
for name in ['availability-0.6-feed','availability-0.75-feed','assumed-new-tritium-feed-100','availability-0.95-feed','density-4.5e+20-fixed-feed','density-5.5e+20-fixed-feed']:
 r=by[name];lines.append(f"| {name} | {r['inputs'][P+'cost_schedule__availability']:.2f} | {r['inputs']['aries_cs_plasma_integration__plasma__amplitude']:.3g} | 100 | {get(r,'plant_ledger','net_electric'):.6f} | {get(r,'lifecycle_accounts','external_shortfall'):.6f} | {get(r,'lifecycle_accounts','curtailed_feed'):.6f} | {price(r):.6f} |")
lines+=['', 'Each of these points fixes independently supplied feed at 100 kg/calendar year and service at 30 million USD2004/year; neither is multiplied by availability again. Hardware, capacities and purchase choices remain fixed. Lower availability/demand can eliminate external purchases, while higher operation crosses the purchase floor and incurs expensive supplemental tritium. The non-monotone LCOE response is therefore conditional fuel-boundary arithmetic, not a reliability or plasma optimum. The density changes also alter net electricity, which reaches the native denominator.','', '## Preserved engineering failures and refusals','', '| Completed adverse case | Net MW | USD2004/MWh | Failed qualified constraints |','| --- | ---: | ---: | --- |']
for r in failures:lines.append(f"| {r['case']} | {r['net_mw']:.6f} | {r['lcoe']:.6f} | "+'; '.join('`'+k+'`='+v for k,v in r['verdicts'].items())+' |')
lines+=['', 'The 5000 m2 helium exchanger case retains its heat-removal failure while producing finite financial output. The explicitly purchased 75000 m2 case passes all represented checks and changes capital through the selected-area price law. The three inherited source cases remain distinct, with their actual thermal failures; no source electricity is substituted into their integrated headline.','', 'Eleven author stock-runtime financial refusal attempts are retained separately in diagnostic-refusals.json. The additional isolated diagnostic route retains full upstream outputs for nonpositive energy, negative rate and source double-financing controls, plus a baseline parity case. It has its own copied runtime/provenance, not a stock StudyRunner completion claim. At nonpositive energy, native calculated power is -571.893206 MW; 505 numeric outputs and 14 predicate records remain, while integrated LCOE is blocked by its dependency. The supplied source-comparison branch can remain defined independently. The negative-rate control blocks both financial branches; the nonzero source-construction guard blocks only the source-financing branch. No refused case is assigned a sentinel price or included in the 64 finite rows.','', '## Source comparison','', 'Source values and their original page references are retained in source-evidence/source-boundary.md and its reviewed page images. The source-conditioned branch uses already-financed capital and supplied 1000 MW with zero second IDC. It retains the integrated case\'s fuel throughput, rather than reconstructing source fusion/fuel physics. It holds each selected case\'s recurring expenses and blanket events; terminal/salvage/overhaul fractions stay fixed, so their absolute capital-based amounts change. It does not reconstruct the source financial convention.','', '| Quantity | Published source | Native integrated feed100 | Native source-conditioned feed100 | Difference / comparability | Units / price year / status |','| --- | ---: | ---: | ---: | --- | --- |']
sc=get(feed,'source_lifecycle_price','lcoe');ic=price(feed)
lines.append(f'| Complete LCOE | 77.6 | {ic:.6f} | {sc:.6f} | Integrated {ic-77.6:+.6f}; source-conditioned {sc-77.6:+.6f}; boundaries differ | USD2004/MWh; source reported, model calculated |')
lines.append(f"| Net power | 1000 | {get(feed,'plant_ledger','net_electric'):.6f} | 1000 | Integrated {get(feed,'plant_ledger','net_electric')-1000:+.6f}; source branch supplied | MW; source reported / integrated calculated / comparison supplied |")
lines.append(f"| Annual energy | 7446000 | {get(feed,'lifecycle_accounts','annual_energy'):.6f} | {get(feed,'source_lifecycle_accounts','annual_energy'):.6f} | Integrated denominator differs; source denominator assumes source85% availability | MWh/year; source-derived and native calculated |")
lines.append(f"| Capital boundary | 5055773960 inclusive | {get(feed,'cost_ledger','overnight'):.2f} overnight; {get(feed,'lifecycle_accounts','financed_capital'):.2f} financed | {get(feed,'source_lifecycle_accounts','financed_capital'):.2f} already financed | Different capital scope and financing convention; not one comparable overnight estimate | USD2004; source-derived inclusive vs native provisional cost |")
lines += ['| Life | 40 full-power years, ambiguous printed availability treatment | 40 calendar years | 40 calendar years | Unmatched time convention | Years; source reported / model assumed |','| Terminal | 0.5 | Gross terminal and salvage shown below | Gross terminal and salvage shown below | Unmatched: source USD1992 per energy versus new USD2004 dated capital fractions | Source USD1992/MWh; model USD2004 event |','| Annual external T purchases | Not established by inspected source (source fuel description identifies D) | Charged remaining shortfall | Same recurring amount held | Scope difference, no zero-source-expense claim | USD2004/year; calculated under assumed supply |']
lines += [f"| Annual O&M | 80,893,344 reverse-derived | {get(feed,'annual_om','annual_om'):.2f} | {get(feed,'annual_om','annual_om'):.2f} held | Source amount is77.6×14%×7,446,000; target-derived, not independently reported | USD2004/year; source target-derived / model supplied allowance |", f"| Operating replacement total | 966,000,000 printed; rounded75m×13=975m | {get(feed,'replacement','lifetime_total'):.2f} across {get(feed,'replacement','event_count'):.0f} events | {get(feed,'replacement','lifetime_total'):.2f} held | Unmatched FPY/calendar life and dated event scope; source lifetime figure is not discounted PV | USD2004; source reported / native selected schedule |"]
lines+=['', '| Capital-scaled allowance at same fractions | Integrated USD2004 | Source-conditioned USD2004 |','| --- | ---: | ---: |']
for f in ('gross_terminal','salvage','other_overhaul_cost'):
 lines.append(f"| {f} | {get(feed,'lifecycle_accounts',f):.6f} | {get(feed,'source_lifecycle_accounts',f):.6f} |")
lines+=['', 'The source-conditioned 75.079576 USD2004/MWh is 2.520424 below 77.6, but that proximity does not identify the source\'s rate, calendar convention, supply assumption or expense schedule. The no-credit source-conditioned value is 473.951454 USD2004/MWh. WI-088 partial budget allocations remain partial and are not competing full LCOEs.','', '## Verification and limits','', 'The frozen native evidence supplies every advertised production quantity. Independent checks cover 364 of 546 numeric outputs per point and rederive all 14 predicates; unchanged constants/pass-through values are not scientific validation. The residual-magnitude and IDC-only absolute tolerances are declared before study execution. Tiny-rate IDC tolerance covers cancellation at the capital scale; other financial channels retain the standard relative comparison. Initial oracle binding/schema preparation corrections are preserved and did not change the model or study inputs.','', 'All finance/cost/feed assumptions are sensitivity-only. The area cases support bounded purchased-equipment accounting/capability comparisons; density cases support fixed-hardware operating propagation. Neither establishes geometry/hydraulic qualification, actual breeding/extraction capability, a market supply path or an optimized plant. Whole-plant scientific qualification remains unsupported. Exact replay and identities are retained in replay.md and results/execution-context.json.']
(R/'report.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'cases':64,'all_scoped_checks_satisfied':64-len(failures),'adverse':len(failures),'verification':'pass','report':str(R/'report.md')}))
